import{_ as o,o as a,c as t,am as r}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"消息队列_RocketMQ_基础","description":"","frontmatter":{"title":"消息队列_RocketMQ_基础","excerpt":"消息队列_RocketMQ_基概念","date":"2024-03-07 20:23:46","updated":"2024-03-07 20:23:46"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/MQ RocketMQ/消息队列_RocketMQ_基础.md","filePath":"中间件/中间件 - 消息队列/MQ RocketMQ/消息队列_RocketMQ_基础.md","lastUpdated":null}'),l={name:"中间件/中间件 - 消息队列/MQ RocketMQ/消息队列_RocketMQ_基础.md"};function s(i,e,n,p,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h3 id="一、基础概念" tabindex="-1">一、基础概念 <a class="header-anchor" href="#一、基础概念" aria-label="Permalink to &quot;一、基础概念&quot;">​</a></h3><h4 id="rocketmq-是什么" tabindex="-1">RocketMQ 是什么 <a class="header-anchor" href="#rocketmq-是什么" aria-label="Permalink to &quot;RocketMQ 是什么&quot;">​</a></h4><p>RocketMQ 是一款开源的分布式消息和流处理平台，由阿里巴巴集团开发并贡献给 Apache 软件基金会。它被设计用于处理大规模、高吞吐量的消息传递，并在阿里巴巴集团内部及众多企业中广泛使用。</p><p>特点：高性能，高可靠，高实时，分布式</p><p>RocketMQ 是发布/订阅 的消息模型</p><p>优点：</p><ul><li>可靠性很好</li><li>单机吞吐量：十万级</li><li>源码是 Java，方便二次开发</li></ul><table tabindex="0"><thead><tr><th>分类</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>高性能</td><td>高吞吐、低延迟，顺序写磁盘与零拷贝，适合集群与高并发场景</td><td></td></tr><tr><td>高可用</td><td>主从架构，多副本容错，支持 Broker 快速切换</td><td></td></tr><tr><td>扩展性</td><td>Topic、Producer、Consumer 可水平扩展，适合大规模部署</td><td>部分分布式特性仍需业务层配合，跨集群场景下运维复杂</td></tr><tr><td>消息模型</td><td>支持顺序、事务、延时、批量消息等多种模型</td><td>顺序消息并发受限，事务消息使用和容错管理较复杂</td></tr><tr><td>监控与追踪</td><td>内置消息轨迹，Dashboard 管控便捷</td><td></td></tr><tr><td>安全性</td><td>支持 ACL，权限粒度可控</td><td></td></tr><tr><td>生态与支持</td><td>多语言支持、社区活跃、企业级应用多</td><td>国际化社区、生态和第三方插件相对 Kafka 略弱</td></tr><tr><td>存储依赖</td><td>-</td><td>磁盘堆积大量消息时 IOPS 需求大，极端场景下需关注物理瓶颈</td></tr><tr><td>易用性</td><td>-</td><td>文档相对 Kafka 略少，使用门槛略高，批量消费不如 Kafka 方便</td></tr></tbody></table><h4 id="消息模型" tabindex="-1">消息模型 <a class="header-anchor" href="#消息模型" aria-label="Permalink to &quot;消息模型&quot;">​</a></h4><p>消息队列有两种模型：<strong>队列模型</strong>和<strong>发布/订阅模型</strong>。RocketMQ 是后者。</p><ul><li>队列模型 <ul><li>队列方式，生产者消费者</li></ul></li><li>主题模型/发布订阅 <ul><li>发布者将消息发送到指定主题中，订阅者需要 <strong>提前订阅主题</strong> 才能接受特定主题的消息。<img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231220201308.png" alt="image.png|500"></li></ul></li></ul><h4 id="rocketmq-的消息模型" tabindex="-1">RocketMQ 的消息模型 <a class="header-anchor" href="#rocketmq-的消息模型" aria-label="Permalink to &quot;RocketMQ 的消息模型&quot;">​</a></h4><blockquote><p>基础模型：<strong>Producer、Broker、Consumer、Topic</strong></p></blockquote><ul><li><strong>Producer</strong>：消息生产者，负责向消息队列发送消息。</li><li><strong>Broker</strong>：消息服务器，负责存储和转发消息，是 Producer 和 Consumer 的中间桥梁。</li><li><strong>Consumer</strong>：消息消费者，从 Broker 拉取或订阅消息进行消费处理。</li><li><strong>Topic</strong>：逻辑上的消息分类，Producer 按 Topic 发送消息，Consumer 可订阅感兴趣的 Topic。</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">participant Producer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">participant Broker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">participant Consumer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Producer-&gt;&gt;Broker: 发送消息 (按 Topic 分类)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Broker-&gt;&gt;Consumer: 推送或等待拉取消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Consumer--&gt;&gt;Broker: 消费成功确认（ACK）</span></span></code></pre></div><h4 id="rocket-mq-的主要概念" tabindex="-1">Rocket MQ 的主要概念 <a class="header-anchor" href="#rocket-mq-的主要概念" aria-label="Permalink to &quot;Rocket MQ 的主要概念&quot;">​</a></h4><table tabindex="0"><thead><tr><th>名称</th><th>中文名</th><th>作用/描述</th><th>备注</th></tr></thead><tbody><tr><td>Message</td><td>消息</td><td>RocketMQ 基本数据单元，包含正文、Topic/Tag/Keys/属性等</td><td>Producer 发送/Consumer接收</td></tr><tr><td>Topic</td><td>主题</td><td>消息一级分类，区分业务主题</td><td>一个 Topic 可含多个队列</td></tr><tr><td>Tag</td><td>标签</td><td>Topic 二级分类，便于细粒度过滤与分流</td><td>可按 Tag 订阅/筛选消息</td></tr><tr><td>Group</td><td>消费组</td><td>一组消费者实例并发消费同一 Topic 下的消息</td><td>保证消息唯一/分布广播模式</td></tr><tr><td>Message Queue</td><td>消息队列</td><td>Topic 下物理存储分片，实现并发消费</td><td>绑定单 Consumer 实例消费</td></tr><tr><td>Offset</td><td>消费偏移量</td><td>消息队列消费游标，标识已消费进度</td><td>便于断点续消费/回溯</td></tr></tbody></table><hr><p>RocketMQ 消息的组成： <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260113214456.png" alt="image.png"></p><h5 id="message" tabindex="-1">Message <a class="header-anchor" href="#message" aria-label="Permalink to &quot;Message&quot;">​</a></h5><p>RocketMQ 的最基本数据单元，由生产者发送到 Broker，再由消费者读取。每条消息通常包含主题（Topic）、内容（Body）、标签（Tag）、消息键（Keys）、属性（Properties）等字段。</p><h5 id="topic" tabindex="-1">Topic <a class="header-anchor" href="#topic" aria-label="Permalink to &quot;Topic&quot;">​</a></h5><p>用于对消息进行逻辑分类。Producer 按 Topic 发送消息，Consumer 订阅 Topic 获取消息。一个 Topic 下可划分多个队列（Message Queue），实现高并发和消费分片。</p><h5 id="tag" tabindex="-1">Tag <a class="header-anchor" href="#tag" aria-label="Permalink to &quot;Tag&quot;">​</a></h5><p>Topic 的二级分类，用于细化筛选消息。Producer 可为消息指定 Tag，Consumer 支持按 Tag 过滤订阅，实现业务分流和细粒度消费。</p><blockquote><p>Topic 和 Tag 的区别</p></blockquote><p>消息发送的时候一般会指定消息体，消息体对象包括 Topic， Tag （可选），消息数据</p><p>其中 Tag是进一步细化Topic消息分类的标签。</p><h5 id="group" tabindex="-1">Group <a class="header-anchor" href="#group" aria-label="Permalink to &quot;Group&quot;">​</a></h5><p>Consumer Group 表示一组消费同一 Topic 的消费者实例。在 <strong>集群模式</strong> 下，同一 Group 的消费实例共同处理 Topic 下的所有消息（避免重复）；在 <strong>广播模式</strong> 下，每个 Group 内所有 Consumer 都接收到完整消息。</p><h5 id="message-queue" tabindex="-1">Message Queue <a class="header-anchor" href="#message-queue" aria-label="Permalink to &quot;Message Queue&quot;">​</a></h5><p>物理实际分区，消息的实际存储地方</p><p>一个 Topic 下的实际存储分片，Broker 按原理可将 Topic 分为多个队列，实现消息并发存储与拉取。消费者可并行处理，每个队列的数据由某个 Consumer 实例负责。</p><h5 id="offset" tabindex="-1">Offset <a class="header-anchor" href="#offset" aria-label="Permalink to &quot;Offset&quot;">​</a></h5><p>Offset 是消费者组在 Queue 的消费位置下标</p><p>标识消费者当前已消费到队列中的哪条消息（唯一编号），用于保证消息不丢失、可断点续消费。Broker 和 Consumer 均管理 Offset，支持精确消费和消息重试/回溯。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260113214838.png" alt="image.png"></p><h4 id="消息的消费模式" tabindex="-1">消息的消费模式 <a class="header-anchor" href="#消息的消费模式" aria-label="Permalink to &quot;消息的消费模式&quot;">​</a></h4><p>消息消费模式有两种：<strong>Clustering</strong>（集群消费）和<strong>Broadcasting</strong>（广播消费）。</p><p>默认情况下就是集群消费，这种模式下<code>一个消费者组共同消费一个主题的多个队列，一个队列只会被一个消费者消费</code>，如果某个消费者挂掉，分组内其它消费者会接替挂掉的消费者继续消费。</p><p>而广播消费消息会发给消费者组中的每一个消费者进行消费。</p><hr><p>消息投递/消费模式</p><table tabindex="0"><thead><tr><th>模式名称</th><th>描述</th><th>适用场景</th></tr></thead><tbody><tr><td>Push 模式</td><td>Broker 自动推送消息到 Consumer（主动通知）</td><td>实时消费、低延迟业务</td></tr><tr><td>Pull 模式</td><td>Consumer 主动从 Broker 拉取消息（定时/轮训）</td><td>高吞吐、灵活控制消费进度</td></tr><tr><td>广播消费</td><td>每个 Consumer 都会收到一份消息</td><td>群体通知、监控日志、同步事件</td></tr><tr><td>集群消费</td><td>多个 Consumer 节点协作消费同一 Topic，消息分摊</td><td>任务分布、业务分片</td></tr></tbody></table><h3 id="二、架构和组件" tabindex="-1">二、架构和组件 <a class="header-anchor" href="#二、架构和组件" aria-label="Permalink to &quot;二、架构和组件&quot;">​</a></h3><h4 id="基础组件" tabindex="-1">基础组件 <a class="header-anchor" href="#基础组件" aria-label="Permalink to &quot;基础组件&quot;">​</a></h4><p>基础组件有：NameServer 注册中心、Broker 消息队列服务器、Producer、Consumer</p><ul><li><code>NameServer</code><ul><li>·去中心化的注册中心：进行Broker节点管理和路由信息管理</li><li>负载均衡，路由管理，注册中心</li><li>操作步骤 <ul><li><ol><li><code>Broker</code> 会将自己的信息注册到 <code>NameServer</code> 中（此时，<code>NameServer</code> 会存放很多 <code>Broker</code> 的信息 ← Broker 的路由表信息）</li></ol></li><li><ol start="2"><li>消费者和生产者从 <code>NameServer</code> 获取路由表信息和对应的 <code>Broker</code> 进行通信(生产者和消费者定期会向 <code>NameServer</code> 去查询相关的 <code>Broker</code> 的信息)</li></ol></li></ul></li><li>多个 NameServer 形成集群，但它们之间不同步信息。客户端（Producer 和 Consumer）可以连接任意一个 NameServer</li></ul></li><li><code>Broker</code><ul><li>消息队列服务器，生产者生产消息到 <code>Broker</code> ，消费者从 <code>Broker</code> 拉取消息并消费。 <ul><li>Broker 可以是 Master 也可以是 Slave。 <ul><li>每个 Master 可以有多个 Slave。Master 负责读写消息，Slave 可以进行消息的同步，保证数据的高可用性。</li></ul></li></ul></li><li>定期向 Name Server 发送心跳包（包含自身的主题信息）；Broker：消息处理的节点中心；NameSpace 管理的路由也是对应节点来处理的；一个Broker 节点下有多个Queue</li><li>消息存储和转发：Broker 是消息存储和转发的核心。生产者将消息发送到 Broker，Broker 负责将消息保存在相应的队列中。</li><li>消息处理：Broker 处理所有与消息相关的操作，包括消息的存储、检索、删除以及向消费者分发消息。</li><li>维护队列状态：Broker 负责维护每个队列的状态，如消息偏移量（Offset），确保消息能够被正确地消费。</li></ul></li><li><code>Producer</code><ul><li>生产者</li><li>生产者会定期向 NameServer 查询 Broker 的信息</li><li>当生产者准备发送消息时，它首先联系 NameServer 以获取 Topic 所在的 Broker 信息。然后，根据这些信息，生产者将消息发送到正确的 Broker 和对应的队列中。</li></ul></li><li><code>Consumer</code><ul><li>消费者</li><li>定期向 NameServer 查询 Broker 的信息</li><li>订阅主题：消费者向 Broker 订阅特定的 Topic。这个过程可能会涉及 NameServer 来找到托管该 Topic 的 Broker。</li><li>消息接收：一旦 Broker 中的 Topic 收到消息，符合条件的消费者（那些订阅了该 Topic 的消费者）就可以接收到这些消息。</li><li><strong>消费模式</strong>： <ul><li>在集群消费模式下，每条消息只会被消费者组中的一个消费者处理。</li><li>在广播消费模式下，每条消息会被发送到消费者组中的所有消费者。</li></ul></li></ul></li></ul><h4 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h4><h5 id="讲述一下nameserver。" tabindex="-1">讲述一下NameServer。 <a class="header-anchor" href="#讲述一下nameserver。" aria-label="Permalink to &quot;讲述一下NameServer。&quot;">​</a></h5><p>NameServer 是 RocketMQ 的路由中心，负责 Broker 信息注册与发布，为 Producer、Consumer 提供快速、可靠的 Topic 路由服务</p><table tabindex="0"><thead><tr><th>特性</th><th>描述</th></tr></thead><tbody><tr><td>组件定位</td><td>轻量级名称服务、分布式注册路由管理</td></tr><tr><td>是否有状态</td><td>无状态、天然分布式</td></tr><tr><td>运维特点</td><td>可随时扩容缩容、无单点</td></tr><tr><td>功能</td><td>Broker 注册/心跳/注销、Producer/Consumer 路由查询</td></tr><tr><td>与 Zookeeper 比较</td><td>更轻量，专用于 Broker 路由和 Topic 查找</td></tr></tbody></table><h5 id="为什么rocketmq不使用zookeeper作为注册中心" tabindex="-1">为什么RocketMQ不使用Zookeeper作为注册中心？ <a class="header-anchor" href="#为什么rocketmq不使用zookeeper作为注册中心" aria-label="Permalink to &quot;为什么RocketMQ不使用Zookeeper作为注册中心？&quot;">​</a></h5><p>RocketMQ主要是保障最终⼀致性，它只需要⼀个轻量级的元数据服 务就⾏了，⽽Zookeeper是强⼀致性的解决⽅案，并且少使⽤⼀个中 间件可以减少维护成本</p><p>还有一方面RocketMQ 是设计是让注册中心<strong>尽量轻量化</strong>，使得消息发送弱依赖注册中心。</p><p><strong>RocketMQ 自研的 NameServer</strong> 专为消息路由注册/查询设计，比 Zookeeper 更轻量、高效、弹性和易运维，完全贴合 RocketMQ 的极端高性能和灵活可扩展的业务场景，而 Zookeeper 主要用于需要分布式一致性、配置、事务等更复杂的系统。因此，RocketMQ 并不采用 Zookeeper 作为其注册中心</p><h4 id="消息发送流程" tabindex="-1">消息发送流程 <a class="header-anchor" href="#消息发送流程" aria-label="Permalink to &quot;消息发送流程&quot;">​</a></h4><p>生产消息和消费消息操作：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312271701523.png" alt="image.png"></p><blockquote><p>Q1：生产者发送消息的流程</p></blockquote><p>生产者组发送消息以及消费者组是如何接受消息：</p><p>在RocketMQ 中，NameServer 负责服务发现和路由管理，当生产者组发送某一个主题的消息时候，Producer Groups 会先从 NameServer 获取到 Topic 主题消息 所在的 Broker 信息，根据这些信息，生产者组会发送消息到正确的 Broker 和 对应的队列中。</p><p>里面的一个核心观点是 Topic ，个人理解主题Topic 是 将Queue进行分类，类似分组、标签（逻辑上）</p><p>而 Queue 的实际作用是 物理实际分区，消息的实际存储地方；消息发送到正确的 Broker 后，Broker 会负责将消息<strong>保存在</strong>相应的队列中。</p><p>Consumer Groups 会从NameServer 查询 Broker 的信息（从 NameServer 来找到托管该 Topic 的 Broker），订阅对应主题的消息，当 一旦 Broker 中的 Topic 收到消息，就可以接收到对应消息。</p><h4 id="路由注册" tabindex="-1">路由注册 <a class="header-anchor" href="#路由注册" aria-label="Permalink to &quot;路由注册&quot;">​</a></h4><ul><li>NameServer 每隔 10 s 扫描 Broker Live Table</li><li>检查上次心跳时间与当前时间的时差，如果超过 120 s，则认为 Broker 不可用，移除路由表中 Broker 相关的信息 <ul><li>Broker 一般会每隔 30s 向 NameServer 报告是否存活</li></ul></li></ul><h4 id="路由剔除" tabindex="-1">路由剔除 <a class="header-anchor" href="#路由剔除" aria-label="Permalink to &quot;路由剔除&quot;">​</a></h4><ul><li>定时扫描判断该路由节点是否可用</li></ul><h4 id="rocketmq的整体工作流程" tabindex="-1">RocketMQ的整体工作流程 <a class="header-anchor" href="#rocketmq的整体工作流程" aria-label="Permalink to &quot;RocketMQ的整体工作流程&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308105913.png" alt="image.png"></p><p>简单来说，RocketMQ是一个分布式消息队列，也就是<code>消息队列</code>+<code>分布式系统</code>。</p><p>作为消息队列，它是<code>发</code>-<code>存</code>-<code>收</code>的一个模型，对应的就是Producer、Broker、Cosumer；作为分布式系统，它要有服务端、客户端、注册中心，对应的就是Broker、Producer/Consumer、NameServer</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308105905.png" alt="image.png"></p><h4 id="rocketmq-的负载均衡是如何实现的" tabindex="-1">RocketMQ 的负载均衡是如何实现的 <a class="header-anchor" href="#rocketmq-的负载均衡是如何实现的" aria-label="Permalink to &quot;RocketMQ 的负载均衡是如何实现的&quot;">​</a></h4><p>RocketMQ实现了客户端负载均衡，包括生产者（Producer）和消费者（Consumer）两个方面。</p><p>生产者</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308201331.png" alt="image.png"></p><p>消费者</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308201406.png" alt="image.png"></p><ul><li>在集群模式下，消息队列被均匀地分配给同一个消费组内的所有消费者，确保在一个时间点，一个消息队列只被一个消费者消费。</li><li>在广播模式下，所有消费者都会消费到所有的消息队列中的消息。</li></ul><h4 id="消息长轮询" tabindex="-1">消息长轮询 <a class="header-anchor" href="#消息长轮询" aria-label="Permalink to &quot;消息长轮询&quot;">​</a></h4><p>消息长轮询优化了消息拉取的过程</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308200609.png" alt="image.png"></p><h3 id="三、功能实现和常用概念" tabindex="-1">三、功能实现和常用概念 <a class="header-anchor" href="#三、功能实现和常用概念" aria-label="Permalink to &quot;三、功能实现和常用概念&quot;">​</a></h3><h4 id="topic-和-queue-的关系" tabindex="-1">Topic 和 Queue 的关系 <a class="header-anchor" href="#topic-和-queue-的关系" aria-label="Permalink to &quot;Topic 和 Queue 的关系&quot;">​</a></h4><blockquote><p>Topic Data ↑ Queue Num ↑</p></blockquote><p>当某个 <code>Topic</code> 消息量很大，应该给它多配置几个队列，并且 <strong>尽量多分布在不同 <code>Broker</code> 上，以减轻某个 <code>Broker</code> 的压力</strong> 。</p><p><code>Topic</code> 消息量都比较均匀的情况下，如果某个 <code>broker</code> 上的队列越多，则该 <code>broker</code> 压力越大。</p><h4 id="消费者和queue-的关系" tabindex="-1">消费者和Queue 的关系 <a class="header-anchor" href="#消费者和queue-的关系" aria-label="Permalink to &quot;消费者和Queue 的关系&quot;">​</a></h4><blockquote><p>Advice Num(Consumer) = Num(Queue)</p></blockquote><p>通常建议消费者组中的消费者数量与主题中的队列数量保持一致</p><ul><li>这样做的目的是为了最大化并行处理的效率。 <ul><li>如果消费者的数量多于队列的数量，那么会有一些消费者实际上没有分配到队列，从而闲置。</li><li>相反，如果消费者的数量少于队列的数量，某些队列可能不会被及时消费，导致消息积压。</li></ul></li></ul><blockquote><p><strong>每个消费组在每个队列上维护一个消费位置</strong></p></blockquote><ul><li><strong>Offset 的作用</strong>：消费位移是指消费者在队列中消费到的位置。它用于跟踪消费者已经消费到哪里，以便在消费者重启或故障后能够从上次的位置继续消费。</li><li><strong>谁来维护</strong>：这个位移是由 Broker 维护的。消费者在处理完消息后，会向 Broker 报告自己的消费位移。</li><li><strong>消息的保留</strong>：队列中的消息通常会在所有消费者组消费之后才会被删除。这意味着，只要有一个消费者组还没有消费某条消息，这条消息就会被保留在队列中。</li></ul><h4 id="消息的持久化和删除" tabindex="-1">消息的持久化和删除 <a class="header-anchor" href="#消息的持久化和删除" aria-label="Permalink to &quot;消息的持久化和删除&quot;">​</a></h4><blockquote><p>概念：消息的存储和删除</p></blockquote><ul><li><strong>数据的持久化</strong>：Broker 负责消息的存储。只要消息还没有被所有订阅的消费者组消费，它就会一直存储在 Broker 中。</li><li><strong>消息的删除</strong>：消息通常在满足一定条件后才会被删除，例如，当所有消费者组都消费了该消息，或者消息达到了其存储的最大时间（如设置了消息的存储时长）。</li></ul><h4 id="topic-和-queue-的关系-1" tabindex="-1">Topic 和 Queue 的关系 <a class="header-anchor" href="#topic-和-queue-的关系-1" aria-label="Permalink to &quot;Topic 和 Queue 的关系&quot;">​</a></h4><blockquote><p>为什么一个主题中需要维护多个队列？</p></blockquote><ol><li><strong>提高并发能力</strong>：在一个主题下配置多个队列的目的是为了提高消息处理的并发能力。这允许多个生产者同时向不同的队列发送消息，同时也允许多个消费者并行地从不同队列中拉取和处理消息。</li><li><strong>负载均衡和效率</strong>：如果一个主题只有一个队列，那么所有的消息都会被顺序地放入这个单一的队列中，这限制了并行处理的可能性。在这种情况下，即使有多个消费者，也只能有一个消费者在任何给定时间处理队列中的消息，从而降低了整体的处理效率。</li></ol><h4 id="负载均衡" tabindex="-1">负载均衡 <a class="header-anchor" href="#负载均衡" aria-label="Permalink to &quot;负载均衡&quot;">​</a></h4><blockquote><p>生产者发送消息（负载均衡转发到 Broker ）</p></blockquote><p>在RocketMQ中，一条消息在正常情况下是不会被发送到多个Broker的</p><p>所谓的负载均衡一般指的是：轮询，随机和其他策略</p><p>然后发送给某一个 Broker ，但是这个 Broker 如果是主从的话，就是消息默认发送到Master节点，Master节点负责将消息复制到Slave节点。</p><h4 id="推拉模式" tabindex="-1">推拉模式 <a class="header-anchor" href="#推拉模式" aria-label="Permalink to &quot;推拉模式&quot;">​</a></h4><blockquote><p>消费者的拉取请求</p></blockquote><p>实际都是主动拉取的，不过消费者端的推送是有一个监听机制（定时拉取，不过对于用户来说这个过程是隐藏的）</p><p>RocketMQ 采用的是拉模式。</p><h4 id="回溯消费" tabindex="-1">回溯消费 <a class="header-anchor" href="#回溯消费" aria-label="Permalink to &quot;回溯消费&quot;">​</a></h4><blockquote><p>官方文档解释</p></blockquote><p>回溯消费是指 <code>Consumer</code> 已经消费成功的消息，由于业务上需求需要重新消费，</p><p>在<code>RocketMQ</code> 中， <code>Broker</code> 在向<code>Consumer</code> 投递成功消息后，<strong>消息仍然需要保留</strong> 。并且重新消费一般是按照时间维度，例如由于 <code>Consumer</code> 系统故障，恢复后需要重新消费 1 小时前的数据，那么 <code>Broker</code> 要提供一种机制，可以按照时间维度来回退消费进度。<code>RocketMQ</code> 支持按照时间回溯消费，时间维度精确到毫秒。</p><h4 id="生产者分组" tabindex="-1">生产者分组 <a class="header-anchor" href="#生产者分组" aria-label="Permalink to &quot;生产者分组&quot;">​</a></h4><p>待整理一下</p><p>消费者分组 🦌</p><ul><li>PushConsumer</li><li>SimpleConsumer</li><li>PullConsumer</li></ul><p>生产者分组和消费者分组</p><blockquote><p>生产者分组</p></blockquote><ol><li><strong>RocketMQ 5.x 版本及以后</strong>： <ul><li>生产者现在是“匿名”的，即不再强调生产者分组（ProducerGroup）的概念。</li><li>在服务端，生产者不需要显式地配置为特定的分组，这简化了生产者的管理。</li></ul></li><li><strong>RocketMQ 3.x 和 4.x 版本</strong>： <ul><li>在这些历史版本中，生产者分组是一个重要的概念，用于标识和管理一组有着相同行为的生产者。</li><li>如果你是从这些旧版本升级到 5.x，那么之前使用的生产者分组可以废弃，不再需要设置，且不会影响当前业务。</li></ul></li></ol><blockquote><p>消费者分组</p></blockquote><ol><li><strong>概念</strong>： <ul><li>消费者分组是多个消费者的一个逻辑分组，这些消费者有着一致的消费行为。</li><li>通过消费者分组，可以实现消费行为的负载均衡和高可用性。</li></ul></li><li><strong>功能</strong>： <ul><li><strong>订阅关系管理</strong>：RocketMQ 以消费者分组的粒度来管理和追溯订阅关系。</li><li><strong>投递顺序性</strong>：服务端支持顺序投递和并发投递，这些投递方式在消费者分组中统一配置。</li><li><strong>消费重试策略</strong>：包括重试次数和死信队列的设置，用于处理消费失败的情况。</li></ul></li><li><strong>版本差异</strong>： <ul><li><strong>5.x 版本</strong>：消费者的消费行为统一由关联的消费者分组在服务端配置和管理，确保同一分组内所有消费者的行为一致。</li><li><strong>3.x/4.x 历史版本</strong>：消费行为由消费者客户端接口定义，需要在消费者客户端设置时确保同一分组下的消费者行为一致。</li></ul></li></ol><p>RocketMQ 5.x 版本中对生产者分组的概念进行了简化，使其成为匿名的，而消费者分组则仍然是一个关键概念，用于管理消费者的行为和策略。</p><h4 id="消费者分组" tabindex="-1">消费者分组 <a class="header-anchor" href="#消费者分组" aria-label="Permalink to &quot;消费者分组&quot;">​</a></h4><h3 id="四、rocketmq支持的消息类型" tabindex="-1">四、RocketMQ支持的消息类型 <a class="header-anchor" href="#四、rocketmq支持的消息类型" aria-label="Permalink to &quot;四、RocketMQ支持的消息类型&quot;">​</a></h3><p>在 RocketMQ 中，一般使用的是普通消息，还有定时消息、顺序消息、事务消息；下面我们分别来了解一下具体的一些使用。</p><blockquote><p>普通消息</p></blockquote><ul><li><strong>业务场景</strong>：适用于大多数标准的消息传递需求，如异步处理、系统解耦、数据分发等。</li><li><strong>使用</strong>：生产者发送消息到指定的主题（Topic），消费者从主题订阅并处理这些消息。消息按照到达 Broker 的顺序存储。</li></ul><p><strong>普通消息生命周期</strong></p><ul><li>初始化：消息被生产者构建并完成初始化，待发送到服务端的状态。</li><li>待消费：消息被发送到服务端，对消费者可见，等待消费者消费的状态。</li><li>消费中：消息被消费者获取，并按照消费者本地的业务逻辑进行处理的过程。 此时服务端会等待消费者完成消费并提交消费结果，如果一定时间后没有收到消费者的响应，RocketMQ 会对消息进行重试处理。</li><li>消费提交：消费者完成消费处理，并向服务端提交消费结果，服务端标记当前消息已经被处理（包括消费成功和失败）。RocketMQ 默认支持保留所有消息，此时消息数据并不会立即被删除，只是逻辑标记已消费。消息在保存时间到期或存储空间不足被删除前，消费者仍然可以回溯消息重新消费。</li><li>消息删除：RocketMQ 按照消息保存机制滚动清理最早的消息数据，将消息从物理文件中删除。</li></ul><h4 id="定时消息" tabindex="-1">定时消息 <a class="header-anchor" href="#定时消息" aria-label="Permalink to &quot;定时消息&quot;">​</a></h4><ul><li><strong>业务场景</strong>：用于那些需要在指定时间点执行的任务，如延迟通知、定时任务等。</li><li><strong>使用</strong>：生产者发送消息时指定一个延时级别，消息将在指定的延时后才被投递。RocketMQ 不支持任意的延时时间，而是提供了几个预设的延时级别（如1分钟、5分钟、10分钟等）。</li></ul><p><strong>定时消息生命周期</strong></p><ul><li>初始化：消息被生产者构建并完成初始化，待发送到服务端的状态。</li><li>定时中：消息被发送到服务端，和普通消息不同的是，服务端不会直接构建消息索引，而是会将定时消息<strong>单独存储在定时存储系统中</strong>，等待定时时刻到达。</li><li>待消费：定时时刻到达后，服务端将消息重新写入普通存储引擎，对下游消费者可见，等待消费者消费的状态。</li><li>消费中：消息被消费者获取，并按照消费者本地的业务逻辑进行处理的过程。 此时服务端会等待消费者完成消费并提交消费结果，如果一定时间后没有收到消费者的响应，RocketMQ 会对消息进行重试处理。</li><li>消费提交：消费者完成消费处理，并向服务端提交消费结果，服务端标记当前消息已经被处理（包括消费成功和失败）。RocketMQ 默认支持保留所有消息，此时消息数据并不会立即被删除，只是逻辑标记已消费。消息在保存时间到期或存储空间不足被删除前，消费者仍然可以回溯消息重新消费。</li><li>消息删除：Apache RocketMQ 按照消息保存机制滚动清理最早的消息数据，将消息从物理文件中删除。</li></ul><p>定时消息的实现逻辑需要先经过定时存储等待触发，定时时间到达后才会被投递给消费者。因此，如果将大量定时消息的定时时间设置为同一时刻，则到达该时刻后会有大量消息同时需要被处理，会造成系统压力过大，导致消息分发延迟，影响定时精度。</p><h4 id="事务消息" tabindex="-1">事务消息 <a class="header-anchor" href="#事务消息" aria-label="Permalink to &quot;事务消息&quot;">​</a></h4><ul><li><strong>业务场景</strong>：适用于需要保证消息发送和本地事务同时成功或失败的场景，如支付和订单服务间的交互。</li><li><strong>使用</strong>： <ul><li>生产者发送半消息（预备消息）。</li><li>执行本地事务（比如数据库操作）。</li><li>根据本地事务执行结果，提交或回滚消息。提交的消息将被消费者消费，回滚的消息将被删除。</li></ul></li></ul><h4 id="顺序消息-顺序消费" tabindex="-1">顺序消息（顺序消费） <a class="header-anchor" href="#顺序消息-顺序消费" aria-label="Permalink to &quot;顺序消息（顺序消费）&quot;">​</a></h4><p>顺序消息分为全局顺序消息和部分顺序消息，全局顺序消息指某个 Topic 下的所有消息都要保证顺序；</p><p>部分顺序消息只要保证每一组消息被顺序消费即可，比如订单消息，只要保证同一个订单 ID 个消息能按顺序消费即可。</p><p>全局顺序消费</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101253.png" alt="image.png"></p><p>部分顺序消息</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101347.png" alt="image.png"></p><p>部分顺序消息：顺序投递，顺序消费</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101509.png" alt="image.png"></p><p>发送端使用 MessageQueueSelector 类来控制 把消息发往哪个 Message Queue 。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101609.png" alt="image.png"></p><p>消费端通过使用 MessageListenerOrderly 来解决单 Message Queue 的消息被并发处理的问题。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101625.png" alt="image.png"></p><hr><ul><li>分为全局消息和分区消息</li><li>全局消息 <ul><li>将一个主题的所有消息都发送到同一个队列中</li><li>消费者从这个队列中顺序拉取并消费消息，从而实现全局顺序。</li></ul></li><li>分区消息 <ul><li>生产者在发送消息时指定消息的Key（业务标识），RocketMQ根据这个Key的hash值将消息发送到指定的队列。</li><li>消费者从这个队列中拉取消息进行消费，由于消息是按顺序发送到队列的，消费者也会按这个顺序来消费消息。</li></ul></li><li>分区消息一般是为了某一个事件的全链路顺序，全局消息是这个类型的全部事件都顺序。</li></ul><h4 id="延迟消息-延时队列" tabindex="-1">延迟消息（延时队列） <a class="header-anchor" href="#延迟消息-延时队列" aria-label="Permalink to &quot;延迟消息（延时队列）&quot;">​</a></h4><p>RocketMQ实现延时消息的方式是通过预设的延时级别来实现的。当发送一条消息时，可以指定这条消息的延时级别。RocketMQ内部定义了多个延时级别，每个级别对应一定的延时时间，如1s、5s、10s等。</p><ol><li><strong>设置延时级别</strong>：生产者在发送消息时，设置消息的延时级别属性（<code>delayTimeLevel</code>）。</li><li><strong>存储延时消息</strong>：Broker接收到这条延时消息后，根据其延时级别，将消息存储在对应的延时队列中。</li><li><strong>计时等待</strong>：消息在延时队列中等待，直到延时时间过去。</li><li><strong>转移至正常队列</strong>：达到延时时间后，消息会从延时队列转移到正常的消费队列中，此时消费者可以消费到这条消息</li></ol><p>RocketMQ的延时队列提供了一种简便的延时消息处理机制，非常适合需要消息定时处理的应用场景。</p><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import org.apache.rocketmq.client.producer.DefaultMQProducer;</span></span>
<span class="line"><span>import org.apache.rocketmq.common.message.Message;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class DelayProducer {</span></span>
<span class="line"><span>    public static void main(String[] args) throws Exception {</span></span>
<span class="line"><span>        // 实例化消息生产者Producer</span></span>
<span class="line"><span>        DefaultMQProducer producer = new DefaultMQProducer(&quot;ExampleProducerGroup&quot;);</span></span>
<span class="line"><span>        // 设置NameServer的地址</span></span>
<span class="line"><span>        producer.setNamesrvAddr(&quot;localhost:9876&quot;);</span></span>
<span class="line"><span>        // 启动Producer实例</span></span>
<span class="line"><span>        producer.start();</span></span>
<span class="line"><span>        int messageCount = 100;</span></span>
<span class="line"><span>        for (int i = 0; i &lt; messageCount; i++) {</span></span>
<span class="line"><span>            // 创建消息，并指定Topic，Tag和消息体</span></span>
<span class="line"><span>            Message msg = new Message(&quot;TestTopic&quot;, &quot;TagA&quot;, (&quot;Hello RocketMQ &quot; + i).getBytes());</span></span>
<span class="line"><span>            // 设置延时级别3，这个时间大约延时10s</span></span>
<span class="line"><span>            msg.setDelayTimeLevel(3);</span></span>
<span class="line"><span>            // 发送消息</span></span>
<span class="line"><span>            producer.send(msg);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        // 如果不再发送消息，关闭Producer实例。</span></span>
<span class="line"><span>        producer.shutdown();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，消息通过设置<code>setDelayTimeLevel(3)</code>来指定延时级别。RocketMQ预定义了多个延时级别，每个级别对应不同的延时时间，从1s到几个小时不等。具体的延时级别和对应的时间可以在RocketMQ的文档中找到或通过查看Broker配置文件（<code>broker.conf</code>）来了解。</p><ul><li>延时消息的使用需要注意，延时级别是预设的，不能自定义具体的延时时间，只能选择最接近的延时级别。</li><li>延时消息可能会因为Broker的重启而导致延时不准确。</li><li>使用延时消息时，要考虑到消息的存储问题，因为消息在延时期间仍占用存储空间。</li></ul><hr><p>原理实现</p><p>先暂存到 SCHEDULE_TOPIC_xxxx 的 Topic 中</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240307102232.png" alt="image.png"></p><h5 id="rocketmq怎么实现延时消息的" tabindex="-1">RocketMQ怎么实现延时消息的？ <a class="header-anchor" href="#rocketmq怎么实现延时消息的" aria-label="Permalink to &quot;RocketMQ怎么实现延时消息的？&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308102037.png" alt="image.png"></p><h4 id="重试消息" tabindex="-1">重试消息 <a class="header-anchor" href="#重试消息" aria-label="Permalink to &quot;重试消息&quot;">​</a></h4><p>重试消息并不是我们业务中主动发送的，而是指当消费者消费消息失败之后，会<strong>间隔一段时间</strong>之后再次消费这条消息</p><p>重试的机制在并发消费模式和顺序消费模式下实现的原理并不相同</p><p><strong>顺序消费</strong></p><p>当消费失败的时候，他并不会将消息发送到服务端，而是直接在本地等1s钟之后重试（无限重试）</p><p>在这个等待的期间其它消息是不能被消费的</p><p><strong>并发消费</strong></p><p>RocetMQ会为<strong>每个消费者组</strong>创建一个重试消息所在的Topic，名字格式为：%RETRY% + 消费者组名称</p><p>举个例子，假设消费者组为<strong>sanyouConsumer</strong>，那么重试Topic的名称为：%RETRY%sanyouConsumer</p><p>当消息消费失败后，RocketMQ会把消息存到这个Topic底下</p><blockquote><p><strong>重试消息是如何实现间隔一段时间来消费呢？</strong></p></blockquote><p>并发消费模式下<strong>间隔一段时间</strong>底层就是使用的延迟消息来实现的</p><p>RocetMQ会为重试消息设置一个延迟级别，并且延迟级别与重试次数的关系为：delayLevel = 3 + 已经重试次数</p><ul><li>比如第一次消费失败，那么已经重试次数就是0，那么此时延迟级别就是3</li><li>对应的默认的延迟时间就是10s，也就是一次消息重试消费间隔时间是10s</li><li>随着重试次数越多，延迟级别也越来越高，重试的间隔也就越来越长，但是最大也是最大延迟级别的时间</li></ul><p>不过需要注意的是，在并发消费模式下，只有集群消费才支持消息重试，对于广播消费模式来说，是不支持消息重试的，消费失败就失败了，不会管。</p><h4 id="死信消息-死信队列" tabindex="-1">死信消息（死信队列） <a class="header-anchor" href="#死信消息-死信队列" aria-label="Permalink to &quot;死信消息（死信队列）&quot;">​</a></h4><p>死信队列用于处理无法被正常消费的消息，即死信消息。</p><p>发送失败自动重试后仍然失败放入到死信队列中</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308103510.png" alt="image.png"></p><p>命名规则：</p><ul><li>RocketMQ为死信队列使用了特殊的Topic命名约定。默认情况下，当消息在消费过程中重试次数超过设定阈值而无法被消费时，这些消息会被自动发送到一个特殊的死信队列。</li><li>这个队列的Topic通常是<strong>原Topic名称前加上<code>%DLQ%</code>前缀</strong>，表示这是一个用于存放死信的队列</li></ul><p>关于重试的说明：</p><ul><li>并发消费的话，最大重试次数默认是16次</li><li>顺序消费，默认最大重试次数就是 Integer.MAX_VALUE，基本上就是无限次重试，所以默认情况下顺序消费的消息几乎不可能成为死信消息</li></ul><h3 id="五、高可用和高级特性" tabindex="-1">五、高可用和高级特性 <a class="header-anchor" href="#五、高可用和高级特性" aria-label="Permalink to &quot;五、高可用和高级特性&quot;">​</a></h3><h4 id="分布式事务" tabindex="-1">分布式事务 <a class="header-anchor" href="#分布式事务" aria-label="Permalink to &quot;分布式事务&quot;">​</a></h4><p>这里建议用实际例子去补充一下具体如何完成的，目前我们讲述一下 RocketMQ 是如何实现分布式事务的。</p><blockquote><p>分布式事务的常见实现方式（每种方法都有其适用场景和局限性）</p></blockquote><ul><li>2PC（两阶段提交）</li><li>三阶段提交（3PC）</li><li>分布式事务框架 <ul><li>Seata</li><li>TCC（Try-Confirm-Cancel）</li></ul></li><li>本地消息表</li><li>消息队列【 事务消息（half 半消息机制）】</li></ul><blockquote><p>RocketMQ 的分布式事务实现</p></blockquote><p>在 RocketMQ 中，其采用的实现机制是：事务消息加上事务反查机制。</p><p>参考一下这篇博客中关于订单关于的一个流程使用： <a href="https://juejin.cn/post/6844904099993878536" target="_blank" rel="noreferrer">https://juejin.cn/post/6844904099993878536</a></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312281351790.png" alt="image.png"></p><p>上述内容提及到自己认为需要注意的点：</p><ul><li>本地事务进行下一步操作后，服务方才会提交或者回滚半消息到 RocketMQ 的节点 Broker</li></ul><p>关于 Half Message，半消息 和 事务状态回查 的一个基本表述：</p><ol><li><strong>事务消息（Half 消息）</strong>： <ul><li><strong>第一步：发送 Half 消息</strong>：所谓的 Half 消息是指一种特殊状态的消息，它在事务完成之前对消费者是不可见的。</li><li><strong>实现机制</strong>：当发送一个事务消息时，RocketMQ 首先存储这个消息，但将其标记为不可见状态（Half 状态）。这是通过改变消息的主题为 <code>RMQ_SYS_TRANS_HALF_TOPIC</code> 实现的，因为消费者通常不订阅这个特殊主题，所以不会消费这些 Half 消息。</li></ul></li><li><strong>事务反查机制</strong>： <ul><li><strong>定时任务</strong>：RocketMQ 会启动一个定时任务，定期检查 <code>RMQ_SYS_TRANS_HALF_TOPIC</code> 中的消息。</li><li><strong>反查请求</strong>：对于每条 Half 消息，RocketMQ 会根据其生产者组向相应的服务发送事务状态回查请求。</li><li><strong>事务状态决定</strong>：根据回查结果，RocketMQ 会决定是提交还是回滚这条消息。如果事务成功，消息将变为正常状态并可被消费；如果事务失败，消息将被回滚或删除。</li></ul></li></ol><hr><p>RocketMQ 主要是依赖半消息，实现的分布式消息事务，通过 二次确认以及消息回查机制实现。</p><p>流程描述：</p><ul><li>1、Producer 向 broker 发送半消息</li><li>2、Producer 端收到响应，消息发送成功，此时消息是半消息，标记为 “不可投递” 状态，Consumer 消费不了。</li><li>3、Producer 端执行本地事务。</li><li>4、正常情况本地事务执行完成，Producer 向 Broker 发送 Commit/Rollback，如果是 Commit，Broker 端将半消息标记为正常消息，Consumer 可以消费，如果是 Rollback，Broker 丢弃此消息。</li><li>5、异常情况，Broker 端迟迟等不到二次确认。在一定时间后，会查询所有的半消息，然后到 Producer 端查询半消息的执行情况。</li><li>6、Producer 端查询本地事务的状态</li><li>7、根据事务的状态提交 commit/rollback 到 broker 端。（5，6，7 是消息回查）</li><li>8、消费者段消费到消息之后，执行本地事务，执行本地事务。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308102444.png" alt="image.png"></p><p>半消息：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308102529.png" alt="image.png"></p><h5 id="事务回查机制" tabindex="-1">事务回查机制 <a class="header-anchor" href="#事务回查机制" aria-label="Permalink to &quot;事务回查机制&quot;">​</a></h5><p>一般会有一个定时机制，然后如果长时间没有收到二次确认，会进行事务回查</p><ul><li>这个是生产者反而是消费者，收到这条消息后，通过本地实现的 checker 接口的 checkLocalTransaction 方法进行检查本地事务是否执行完成，并将结果告知 MQ 服务器。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240307155659.png" alt="image.png"></p><h4 id="高可用" tabindex="-1">高可用 <a class="header-anchor" href="#高可用" aria-label="Permalink to &quot;高可用&quot;">​</a></h4><p>高可用情景下，</p><ul><li>会构建 <code>broker</code> 集群并且进行主从部署，同时<code>NameServer</code> 也进行集群部署。</li><li>同步复制 + 异步刷盘</li></ul><p>NameServer因为是无状态，且不相互通信的，所以只要集群部署就可以保证高可用。</p><p>RocketMQ的高可用主要是在体现在Broker的读和写的高可用，Broker的高可用是通过<code>集群</code>和<code>主从</code>实现的。</p><blockquote><p><strong>看一下这句话：关于如何实现写的高可用</strong></p></blockquote><ul><li>当 Master 挂机之后，其他节点的 Master 是仍然可用的</li><li>该节点下的Slave 仍然是提供读服务的，但是如果需要从 Slave 改为 Master ，需要修改配置文件</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308105413.png" alt="image.png"></p><p>官网架构图</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312211545167.png" alt="image.png"></p><p>构建 <code>broker</code> 集群并且进行主从部署，同时<code>NameServer</code> 也进行集群部署（去中心化）</p><p>第一，构建 <code>broker</code> 集群并且进行主从部署，此时，消息会分布在多个 <code>broker</code></p><p>当某个 <code>Broker</code> 宕机，在<code>Rocketmq</code> 的 <code>master/slave</code> 结构下，<code>salve</code> 定时从 <code>master</code> 同步数据(同步刷盘或者异步刷盘)，如果 <code>master</code> 宕机，则 <code>slave</code> 提供消费服务，但是不能写入消息</p><p>第二， <code>NameServer</code> 进行了集群部署（ <strong>去中心化</strong> 的，没有主节点）；</p><p><code>Broker 会和所有 NameServer 保持长连接 ，并且在每隔 30 秒 </code>Broker<code>会向所有</code>Nameserver<code>发送心跳，心跳包含了自身的</code>Topic<code>配置信息，这个步骤就对应图中的</code>Routing Info\`</p><p>第三，在生产者需要向 <code>Broker</code> 发送消息的时候，<strong>需要先从 <code>NameServer</code> 获取关于 <code>Broker</code> 的路由信息</strong>，然后通过 <strong>轮询</strong> 的方法去向每个队列中生产数据以达到 <strong>负载均衡</strong> 的效果。</p><p>第四、消费者通过 <code>NameServer</code> 获取所有 <code>Broker</code> 的路由信息后，向 <code>Broker</code> 发送 <code>Pull</code> 请求来获取消息数据。</p><p><code>Consumer</code> 可以以两种模式启动—— <strong>广播（Broadcast）和集群（Cluster）</strong>。广播模式下，一条消息会发送给 <strong>同一个消费组中的所有消费者</strong> ，集群模式下消息只会发送给一个消费者。</p><hr><h4 id="消息过滤" tabindex="-1">消息过滤 <a class="header-anchor" href="#消息过滤" aria-label="Permalink to &quot;消息过滤&quot;">​</a></h4><p>有两种方案：</p><ul><li><p>一种是在 Broker 端按照 Consumer 的去重逻辑进行过滤，这样做的好处是避免了无用的消息传输到 Consumer 端，缺点是加重了 Broker 的负担，实现起来相对复杂。</p></li><li><p>另一种是在 Consumer 端过滤，比如按照消息设置的 tag 去重，这样的好处是实现起来简单，缺点是有大量无用的消息到达了 Consumer 端只能丢弃不处理。</p></li></ul><p>一般采用Cosumer端过滤，如果希望提高吞吐量，可以采用Broker过滤。</p><p>对消息的过滤有三种方式：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308101827.png" alt="image.png"></p><ul><li>根据Tag过滤：这是最常见的一种，用起来高效简单</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DefaultMQPushConsumer consumer = new DefaultMQPushConsumer(&quot;CID_EXAMPLE&quot;);  </span></span>
<span class="line"><span>consumer.subscribe(&quot;TOPIC&quot;, &quot;TAGA || TAGB || TAGC&quot;);</span></span></code></pre></div><ul><li>SQL 表达式过滤：SQL表达式过滤更加灵活</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DefaultMQPushConsumer consumer = new DefaultMQPushConsumer(&quot;please_rename_unique_group_name_4&quot;);  </span></span>
<span class="line"><span>// 只有订阅的消息有这个属性a, a &gt;=0 and a &lt;= 3  </span></span>
<span class="line"><span>consumer.subscribe(&quot;TopicTest&quot;, MessageSelector.bySql(&quot;a between 0 and 3&quot;);  </span></span>
<span class="line"><span>consumer.registerMessageListener(new MessageListenerConcurrently() {  </span></span>
<span class="line"><span>   @Override  </span></span>
<span class="line"><span>   public ConsumeConcurrentlyStatus consumeMessage(List&lt;MessageExt&gt; msgs, ConsumeConcurrentlyContext context) {  </span></span>
<span class="line"><span>       return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;  </span></span>
<span class="line"><span>   }  </span></span>
<span class="line"><span>});  </span></span>
<span class="line"><span>consumer.start();</span></span></code></pre></div><ul><li>Filter Server 方式：最灵活，也是最复杂的一种方式，允许用户自定义函数进行过滤</li></ul><h3 id="六、读写-内存、日志" tabindex="-1">六、读写（内存、日志） <a class="header-anchor" href="#六、读写-内存、日志" aria-label="Permalink to &quot;六、读写（内存、日志）&quot;">​</a></h3><h4 id="broker-如何保存数据-消息持久化" tabindex="-1">Broker 如何保存数据（ 消息持久化） <a class="header-anchor" href="#broker-如何保存数据-消息持久化" aria-label="Permalink to &quot;Broker 如何保存数据（ 消息持久化）&quot;">​</a></h4><ul><li>CommitLog 消息存储文件</li><li>ComsumerQueue 消费消息队列索引文件</li><li>Indexfile 消息索引（快速检索消息）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308142459.png" alt="image.png"></p><p>RocketMQ主要的存储文件包括CommitLog文件、ConsumeQueue文件、Indexfile文件。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308110801.png" alt="image.png"></p><p>消息存储的整体设计</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308110842.png" alt="image.png"></p><p>以下是这些组件的功能和它们在整个存储结构中的作用：</p><h5 id="commitlog-核心文件" tabindex="-1">CommitLog 核心文件 <a class="header-anchor" href="#commitlog-核心文件" aria-label="Permalink to &quot;CommitLog   核心文件&quot;">​</a></h5><ul><li><strong>功能</strong>：CommitLog 是消息存储的核心文件，它存储了生产者写入的消息主体内容及其元数据。</li><li><strong>存储结构</strong>：CommitLog 文件的大小默认为1GB，文件命名基于起始偏移量，例如 <code>00000000001073741824</code>。</li><li><strong>写入方式</strong>：消息主要是顺序写入CommitLog文件，提高了写入效率。当一个文件写满后，写入会继续在下一个文件。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308110951.png" alt="image.png"></p><h5 id="consumequeue-索引文件" tabindex="-1">ConsumeQueue 索引文件 <a class="header-anchor" href="#consumequeue-索引文件" aria-label="Permalink to &quot;ConsumeQueue   索引文件&quot;">​</a></h5><ul><li><strong>功能</strong>：ConsumeQueue 作为消费消息的索引，提升读取效率。</li><li><strong>结构</strong>：ConsumeQueue 保存了特定Topic下队列消息在CommitLog中的起始物理偏移量、消息大小和消息Tag的HashCode值。</li><li><strong>存储路径</strong>：采用 <code>topic/queue/file</code> 的三层组织结构，文件路径为 <code>$HOME/store/consumequeue/{topic}/{queueId}/{fileName}</code>。</li><li><strong>条目组织</strong>：每个条目固定20字节，包括commitlog的物理偏移量、消息长度和tag hashcode，允许像数组一样随机访问每个条目。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308111131.png" alt="image.png"></p><h5 id="indexfile" tabindex="-1">IndexFile <a class="header-anchor" href="#indexfile" aria-label="Permalink to &quot;IndexFile&quot;">​</a></h5><ul><li><strong>功能</strong>：提供了通过key或时间区间查询消息的能力，但不涉及消息的主体内容。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308111226.png" alt="image.png"></p><h5 id="总结-🐉" tabindex="-1">总结 🐉 <a class="header-anchor" href="#总结-🐉" aria-label="Permalink to &quot;总结  🐉&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308141410.png" alt="image.png"></p><p>ReputMessageService 服务会将对应的 CommitLog 文件中的消息异步更新内容到 ComsumeQueue 和 IndexFile 中</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308141719.png" alt="image.png"></p><p>RocketMQ 是默认开启 Broker 持久化机制的，消费者 Comsumer 的消费实际是根据 ComsumerQueue 来进行消费的。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308142224.png" alt="image.png"></p><h4 id="高性能读写" tabindex="-1">高性能读写 <a class="header-anchor" href="#高性能读写" aria-label="Permalink to &quot;高性能读写&quot;">​</a></h4><blockquote><p>RocketMQ怎么对文件进行读写的</p></blockquote><p>RocketMQ对文件的读写巧妙地利用了操作系统的一些高效文件读写方式——<code>PageCache</code>、<code>顺序读写</code>、<code>零拷贝</code>。</p><h5 id="pagecache、顺序读取" tabindex="-1">PageCache、顺序读取 <a class="header-anchor" href="#pagecache、顺序读取" aria-label="Permalink to &quot;PageCache、顺序读取&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308142836.png" alt="image.png"></p><p>顺序读写提高了 CommitLog 和 ComsumerQueue 的写入和读取速率</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308182341.png" alt="image.png"></p><p>关于 PageCache 的理解，因为 CommitLog 是顺序写入的，而 PageCache 技术能够当第一次加载文件的时候会将数据放入到缓存中，通过直接对内存的读取加快对消息处理的性能。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308183931.png" alt="image.png"></p><h5 id="零拷贝" tabindex="-1">零拷贝 <a class="header-anchor" href="#零拷贝" aria-label="Permalink to &quot;零拷贝&quot;">​</a></h5><p>通过了零拷贝技术提高了⽂件传输速度，实现方式是 mmap</p><ul><li>mmap 就是通过⽂件位置与进程地址空间建⽴映射关系，程序可 以直接访问⽂件内容</li><li>这种机制在Java中是通过MappedByteBuffer实现的</li></ul><hr><p>传统方式：</p><p>在操作系统中，使用传统的方式，数据需要经历几次拷贝，还要经历用户态/内核态切换</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308184631.png" alt="image.png"></p><ol><li>从磁盘复制数据到内核态内存；</li><li>从内核态内存复制到用户态内存；</li><li>然后从用户态内存复制到网络驱动的内核态内存；</li><li>最后是从网络驱动的内核态内存复制到网卡中进行传输</li></ol><p>零拷贝方式：</p><p>可以通过零拷贝的方式，<strong>减少用户态与内核态的上下文切换</strong>和<strong>内存拷贝的次数</strong>，用来提升I/O的性能。零拷贝比较常见的实现方式是<strong>mmap</strong>，这种机制在Java中是通过MappedByteBuffer实现的。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308190931.png" alt="image.png"></p><p>零拷贝的好处：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308185040.png" alt="image.png"></p><p>看一下这个对比：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308190654.png" alt="image.png"></p><p>扩展：</p><p>RocketMQ主要通过MappedByteBuffer对文件进行读写操作。</p><p>其中，利用了NIO中的FileChannel模型将磁盘上的物理文件直接映射到用户态的内存地址中（这种Mmap的方式减少了传统IO，将磁盘文件数据在操作系统内核地址空间的缓冲区，和用户应用程序地址空间的缓冲区之间来回进行拷贝的性能开销），将对文件的操作转化为直接对内存地址进行操作，从而极大地提高了文件的读写效率（正因为需要使用内存映射机制，故RocketMQ的文件存储都使用定长结构来存储，方便一次将整个文件映射至内存）</p><h4 id="刷盘机制" tabindex="-1">刷盘机制 <a class="header-anchor" href="#刷盘机制" aria-label="Permalink to &quot;刷盘机制&quot;">​</a></h4><h5 id="同步刷盘和异步刷盘" tabindex="-1">同步刷盘和异步刷盘 <a class="header-anchor" href="#同步刷盘和异步刷盘" aria-label="Permalink to &quot;同步刷盘和异步刷盘&quot;">​</a></h5><p>在 RocketMQ 中，同步刷盘和异步刷盘是两种不同的消息持久化策略，它们各有优劣，并适用于不同的业务场景。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312281520496.png" alt="image.png"></p><p>以下是对这两种策略的详细说明和比较：</p><blockquote><p>同步刷盘（SYNC_FLUSH）</p></blockquote><ul><li><strong>工作原理</strong>：在同步刷盘模式下，每当生产者发送一条消息，Broker 需要将消息写入磁盘并完成刷盘操作后，才会向生产者返回确认（ACK）。只有收到这个确认，生产者才知道消息已经安全存储。</li><li><strong>优点</strong>：提供了更高的消息可靠性。即使在Broker意外宕机的情况下，也不会丢失已确认的消息。</li><li><strong>缺点</strong>：影响性能。由于每条消息都需要等待磁盘写入完成，这会增加消息的延迟时间，降低吞吐量。</li><li><strong>适用场景</strong>：适用于对消息可靠性有极高要求的场景，如金融交易、重要业务数据处理等。</li></ul><blockquote><p>异步刷盘（ASYNC_FLUSH）</p></blockquote><ul><li><strong>工作原理</strong>：在异步刷盘模式下，Broker 将消息写入内存后，就立即向生产者返回确认。实际的刷盘操作是由后台线程异步完成的，不会阻塞消息的发送。</li><li><strong>优点</strong>：提高了性能和吞吐量。由于消息发送不需要等待磁盘操作完成，因此减少了延迟。</li><li><strong>缺点</strong>：消息可靠性降低。如果Broker在消息还未刷入磁盘前发生宕机，那么这部分消息可能会丢失。</li><li><strong>适用场景</strong>：适用于对性能要求较高，但对消息可靠性要求不是特别严格的场景，如日志收集、一些非关键的业务通知等。</li></ul><p><strong>刷盘策略的设置</strong></p><ul><li><strong>配置参数</strong>：在 RocketMQ 中，可以通过设置Broker的<code>FlushDiskType</code>参数来调整刷盘策略。</li><li>可以选择<code>ASYNC_FLUSH</code>（异步刷盘）或<code>SYNC_FLUSH</code>（同步刷盘）。</li></ul><p>同步刷盘和异步刷盘在消息可靠性和性能之间提供了不同的平衡点。</p><p>在实际应用中，应根据业务需求的不同，选择最合适的刷盘策略。对于那些要求高可靠性的场景，同步刷盘是更好的选择；而对于那些更看重性能和吞吐量的应用，异步刷盘则更为适合</p><h5 id="同步复制和异步复制" tabindex="-1">同步复制和异步复制 <a class="header-anchor" href="#同步复制和异步复制" aria-label="Permalink to &quot;同步复制和异步复制&quot;">​</a></h5><p>同步复制和异步复制在 RocketMQ 中指的是主从Broker之间的数据复制方式，这直接影响消息的可靠性和系统的可用性。这两种复制策略在保证数据一致性和提高系统性能之间提供了不同的平衡点。以下是对这两种策略的详细说明和比较：</p><blockquote><p>同步复制（同步双写）</p></blockquote><ul><li><strong>工作原理</strong>：在同步复制模式下，当消息被写入主Broker后，它必须同时被复制到从Broker上。只有当消息在主从Broker上都成功写入后，才向生产者返回写入成功的确认。</li><li><strong>优点</strong>：提高了数据的可靠性。即使主Broker宕机，从Broker上仍然有消息的完整副本。</li><li><strong>缺点</strong>：影响性能。由于消息写入操作需要在主从Broker上都完成，这可能导致较高的延迟和降低吞吐量。</li><li><strong>适用场景</strong>：适用于对数据可靠性要求极高的场景，如金融交易。</li></ul><blockquote><p>异步复制</p></blockquote><ul><li><strong>工作原理</strong>：在异步复制模式下，当消息写入主Broker之后，系统就直接返回写入成功。消息的复制到从Broker是异步进行的。</li><li><strong>优点</strong>：提高了性能。由于不需要等待从Broker确认，消息的写入和确认速度更快。</li><li><strong>缺点</strong>：可能存在数据不一致的风险。如果主Broker在数据复制完成前宕机，从Broker可能缺少最新的数据。</li><li><strong>适用场景</strong>：适用于对性能要求较高，但数据可靠性要求不是极端严格的场景。</li></ul><blockquote><p>可用性与顺序性的考虑</p></blockquote><ul><li><strong>可用性问题</strong>：由于RocketMQ不支持自动主从切换，如果主Broker宕机，整个系统将无法继续生产消息。虽然消费者可以从从Broker消费消息，但在主Broker宕机期间会存在短暂的主从数据不一致情况。</li><li><strong>解决方案</strong>：通过部署多个主从集群（多Broker架构）来提高可用性。每个Topic分布在不同的Broker中，可以在一定程度上解决单个Broker宕机问题。</li><li><strong>顺序性问题</strong>：在多Broker架构下，如果某个主Broker负责特定顺序消息宕机，其他Broker无法替代它处理这些消息，可能影响消息的顺序性。</li><li><strong>Dledger</strong>：RocketMQ通过引入Dledger技术，支持半数以上节点的消息复制后才确认写入成功，并支持主节点的动态选举，解决了严格顺序性和高可用性的问题。</li></ul><p>同步复制和异步复制在RocketMQ中提供了不同的数据一致性和性能平衡。在设计系统时，需要根据业务需求的具体情况选择合适的复制策略。</p><p>Dledger作为一种解决方案，虽然提高了可用性和顺序性保证，但在选举过程中可能会暂时无法提供服务，并且对节点的数量有一定要求。在实际应用中，需综合考虑业务场景的特性和对数据可靠性、系统性能的具体需求来决定使用哪种复制策略。</p><h3 id="七、常见生产问题" tabindex="-1">七、常见生产问题 <a class="header-anchor" href="#七、常见生产问题" aria-label="Permalink to &quot;七、常见生产问题&quot;">​</a></h3><h4 id="消息发送有时候会遇到的问题-消息过大、发送异常" tabindex="-1">消息发送有时候会遇到的问题（消息过大、发送异常） <a class="header-anchor" href="#消息发送有时候会遇到的问题-消息过大、发送异常" aria-label="Permalink to &quot;消息发送有时候会遇到的问题（消息过大、发送异常）&quot;">​</a></h4><blockquote><p>发送消息会遇到的一些问题（特殊情况处理）</p></blockquote><ul><li>不建议单一进程创建大量生产者 <ul><li>对于生产者的创建和初始化，建议遵循够用即可、最大化复用原则</li></ul></li><li>不建议频繁创建和销毁生产者</li></ul><blockquote><p>创建和销毁生产者</p></blockquote><p>正确示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer p = ProducerBuilder.build();</span></span>
<span class="line"><span>for (int i =0;i&lt;n;i++){</span></span>
<span class="line"><span>    Message m= MessageBuilder.build();</span></span>
<span class="line"><span>    p.send(m);</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span>p.shutdown();</span></span></code></pre></div><p><strong>发送异常</strong></p><p>选择队列后会与 Broker 建立连接，通过网络请求将消息发送到 Broker 上，如果 Broker 挂了或者网络波动发送消息超时此时 RocketMQ 会进行重试。</p><p>重新选择其他 Broker 中的消息队列进行发送，默认重试两次，可以手动设置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>producer.setRetryTimesWhenSendFailed(5);</span></span></code></pre></div><p><strong>消息过大</strong></p><p>消息超过 4k 时 RocketMQ 会将消息压缩后在发送到 Broker 上，减少网络资源的占用。</p><h4 id="消息堆积问题" tabindex="-1">消息堆积问题 <a class="header-anchor" href="#消息堆积问题" aria-label="Permalink to &quot;消息堆积问题&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240307135759.png" alt="image.png"></p><p>一般是采用增加消费者实例的方式</p><p>个人理解：如果是应对生产快的，一方面是需要需要这个队列数量和消费者数量，然后应对堆积的情况，就要加一个中转的，把这个堆积的消息分散到多个Queu，然后多个Comsumer消费</p><hr><p>发生了消息积压，这时候就得想办法赶紧把积压的消息消费完，就得考虑提高消费能力，一般有两种办法：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308100619.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308100915.png" alt="image.png"></p><p>消息迁移扩容消费 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240307105817.png" alt="image.png"></p><h4 id="如何保证消息不丢失" tabindex="-1">如何保证消息不丢失 <a class="header-anchor" href="#如何保证消息不丢失" aria-label="Permalink to &quot;如何保证消息不丢失&quot;">​</a></h4><p>可能会在这三个阶段发生丢失：生产阶段、存储阶段、消费阶段。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308094409.png" alt="image.png"></p><ul><li>可能的点：生产 → Broker；Broker 持久化；Broker → 消费</li><li>生产 → Broker <ul><li>RockerMQ生产端有三种发送模式 <ul><li>同步发送（需要等 Broker 有反馈之后才能继续发）</li><li>单向发送（生产端直接发）</li><li>异步发送（发送消息的同时注册一个回调 去处理响应，安全性低，容易丢消息）</li></ul></li><li>防止消息丢失，可以采用同步发送</li></ul></li><li>Broker 持久化 <ul><li>采用同步刷盘以及2PC 两阶段提交，来保证同步时不会丢消息</li><li>异步刷盘一断电就会丢消息</li></ul></li><li>Broker → 消费 <ul><li>采用同步消费机制，不要使用异步消费机制 <ul><li>在同步消费情况下，消费完消息之后再去给Broker端反馈，然后Broker端会去维护消息偏移量，如果消费失败可以进⾏⼀定次数的重试</li><li>在异步消费情况下，消费完消息的同时也会向Broker端反馈，然后Broker端会去维护消息偏移量，如果处理失败了，不会进⾏重试因为偏移量已经变更</li></ul></li></ul></li><li>另外RocketMQ服务需要有降级⽅案，对于RocketMQ来说，NameServer挂了，本身就⽆法保证消息不丢失了，所以应对这种场景，我们可以使⽤服务降级⽅案，将消息暂存到Redis、⽂件或内存中，等MQ服务恢复之后再将消息转移过去</li></ul><p>生产阶段</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308094540.png" alt="image.png"></p><p>生产者可以利用RocketMQ提供的查询API来确认消息是否已经成功存储在Broker上。</p><p>存储阶段</p><p>如果需要保证消息不丢失，可以使用 同步复制（节点主从） + 同步刷盘（日志存储）</p><p>不过一般集群是 同步复制 + 异步刷盘</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308094801.png" alt="image.png"><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308094823.png" alt="image.png"></p><p>消费阶段</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308095216.png" alt="image.png"></p><h4 id="如何避免重复消费" tabindex="-1">如何避免重复消费 <a class="header-anchor" href="#如何避免重复消费" aria-label="Permalink to &quot;如何避免重复消费&quot;">​</a></h4><p>处理消息重复问题，主要有业务端自己保证，主要的方式有两种：<strong>业务幂等</strong>和<strong>消息去重</strong>。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240308095941.png" alt="image.png"></p><p>在消息队列系统中，由于各种原因（如网络波动、Broker 重启等），消息可能会被重复发送给消费者。</p><blockquote><p>实现幂等性的方法</p></blockquote><ul><li>1、通过唯一标识符标记某条消息</li><li>2、通过数据库唯一约束或者唯一主键进行幂等操作</li><li>3、分布式锁：通过 Redis 的 setnx 进行判断是否相同标识符</li></ul><hr><p>参考：</p><ul><li><a href="https://www.yuque.com/quzuopeng/gnbc16/aa63cam94sbc80y1" target="_blank" rel="noreferrer">https://www.yuque.com/quzuopeng/gnbc16/aa63cam94sbc80y1</a></li><li><a href="https://javaguide.cn/high-performance/message-queue/rocketmq-questions.html" target="_blank" rel="noreferrer">https://javaguide.cn/high-performance/message-queue/rocketmq-questions.html</a></li><li><a href="https://www.bilibili.com/video/BV1ua4y1N7P2?p=17&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1ua4y1N7P2?p=17&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0</a></li><li><a href="https://rocketmq.apache.org/zh/docs/quickStart/01quickstart/" target="_blank" rel="noreferrer">https://rocketmq.apache.org/zh/docs/quickStart/01quickstart/</a></li><li><a href="https://doocs.github.io/advanced-java/#/docs/high-concurrency/how-to-ensure-high-availability-of-message-queues" target="_blank" rel="noreferrer">https://doocs.github.io/advanced-java/#/docs/high-concurrency/how-to-ensure-high-availability-of-message-queues</a></li><li><a href="http://learn.lianglianglee.com/%E6%96%87%E7%AB%A0/RocketMQ%20%E9%9D%A2%E8%AF%95%E9%A2%98%E9%9B%86%E9%94%A6.md" target="_blank" rel="noreferrer">http://learn.lianglianglee.com/文章/RocketMQ 面试题集锦.md</a></li><li><a href="https://www.cnblogs.com/javazhiyin/p/13327925.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/javazhiyin/p/13327925.html</a></li><li><a href="https://mp.weixin.qq.com/s/IvBt3tB_IWZgPjKv5WGS4A" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/IvBt3tB_IWZgPjKv5WGS4A</a> 🚩</li><li><a href="https://www.bilibili.com/video/BV1ua4y1N7P2" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1ua4y1N7P2</a></li></ul>`,362)])])}const g=o(l,[["render",s]]);export{h as __pageData,g as default};
